// ===== the Device Forge engine =====
// Original SVG generator. Follows the rules Tolkien set down for Elvish heraldry
// (shape by bearer, rank by rim-points, radial symmetry) as recorded in his own note
// quoted in Hammond & Scull and in Zurek, 'Heraldry in J.R.R. Tolkien's Legendarium',
// The Coat of Arms 4th ser. 5 (2022), 145-182. No artwork is copied; the shapes are drawn
// from arithmetic here.
// A square device on the plates fills its panel almost edge to edge; 0.84 left a
// margin the paintings do not have. One constant so the four places cannot drift apart.
var ARDA_SQ=0.94;
var ARDA_GRAD_N=0;   // unique ids for the gradients a course may ask for
// Measured off every plate: Tolkien's lozenge is a SQUARE standing on its point --
// the ink box of all thirteen lozenge plates is exactly 1.00 wide for 1.00 tall, where
// the forge had been drawing 0.82.  His Gondolin shields are 0.50 -- twice as tall as
// wide -- where the forge drew 0.75.  Both are corrected here, once.
var ARDA_LZ=1.00;      // lozenge half-width as a fraction of R
// TOLKIEN'S OWN CONSTRUCTION, taken off the two diagrams of it on Wikimedia Commons
// (Lozenge_four_points.svg and Lozenge_eight_points.svg, Chiswick Chap, CC BY-SA 4.0),
// which draw the lozenge with the circles its points are set against:
//
//   the lozenge is EXACTLY a square on its point            w/h = 1.0000
//   the inner circle is the same whatever the rank          0.266 of the half-diagonal
//   the outer circle grows with the number of points        0.490 for four
//                                                           0.609 for eight
//
// So a device of his has a heart about a quarter of the way out, a ring at about half
// (four points) or three-fifths (eight), and the points running from that ring to the
// rim. A forged device that ignores these sits wrong however well its charges are drawn.
var ARDA_TOL={inner:0.266, outer4:0.490, outer8:0.609};
window.ardaTolkienOuter=function(points){
 // between and beyond the two measured ranks, straight-line in the number of points
 if(!points||points<=4) return ARDA_TOL.outer4;
 if(points>=8) return ARDA_TOL.outer8;
 return ARDA_TOL.outer4+(ARDA_TOL.outer8-ARDA_TOL.outer4)*(points-4)/4;
};
window.ARDA_TOL=ARDA_TOL;
var ARDA_SHW=0.495;    // shield half-width; height stays 0.92R above, 1.06R below
