window.ARDA_REALM_DEVICE={doriath:"thingol",gondolin:"turgon",nargothrond:"finrod",khazaddum:"durin",erebor:"durin",ironhills:"durin",lindon:"gilgalad",eregion:"feanor",lorien:"galadriel",rivendell:"elrond",mordor:"redeye",dolguldur:"redeye",gondor:"gondor",reunited:"telcontar",angmar:"morgul",morgul:"morgul",rohan:"rohan",isengard:"whitehand",harad:"serpent"};
/*TAX*/window.ARDA_HERALD_TAX=[["The Valar", ["The Powers of Arda"]], ["Eldar", ["The House of Finwë", "Doriath & the Sindar", "The Teleri & the Havens", "The Silvan Realms", "The Houses of Gondolin", "Gil-galad & the Half-elven", "Jewels & Emblems of the Elder Days"]], ["The Kingdoms of Men", ["The Three Houses of the Edain", "Númenor & the North-kingdom", "Gondor", "Rohan", "The Northmen & the Lake"]], ["The Khazâd", ["Durin's Folk"]], ["The Enemy", ["Angband & Mordor", "Isengard", "the South & East", "the Misty Mountains"]], ["The Istari", ["the Wandering Wizards"]], ["Inferred under C120", ["Houses", "Realms", "Places"]]];
